class Solution {
public:
    int minSwaps(vector<int>& data) {
        int w = 0;
        for (int x : data) w += x;
        if (w <= 1) return 0;

        int curr_ones = 0;
        for (int i = 0; i < w; ++i) curr_ones += data[i];
        int max_ones = curr_ones;
        for (int i = w; i < (int)data.size(); ++i) {
            curr_ones += data[i] - data[i - w];
            max_ones = max(max_ones, curr_ones);
        }
        return w - max_ones;
    }
};

class Solution {
    public int minSwaps(int[] data) {
        int w = 0;
        for (int x : data) w += x;
        if (w <= 1) return 0;

        int currOnes = 0;
        for (int i = 0; i < w; i++) currOnes += data[i];
        int maxOnes = currOnes;
        for (int i = w; i < data.length; i++) {
            currOnes += data[i] - data[i - w];
            maxOnes = Math.max(maxOnes, currOnes);
        }
        return w - maxOnes;
    }
}

var minSwaps = function(data) {
    let w = 0;
    for (const x of data) w += x;
    if (w <= 1) return 0;

    let currOnes = 0;
    for (let i = 0; i < w; i++) currOnes += data[i];
    let maxOnes = currOnes;
    for (let i = w; i < data.length; i++) {
        currOnes += data[i] - data[i - w];
        if (currOnes > maxOnes) maxOnes = currOnes;
    }
    return w - maxOnes;
};
